use ratatui::{prelude::*, widgets::*};
use crate::{app::{App, Mode}, views, widgets::{modal, toast}};
pub fn draw(f:&mut Frame, app:&App){ let area=f.area(); if area.width<80 || area.height<24 { let p=Paragraph::new("SSHDeck needs a larger terminal window.
Minimum recommended size: 100x30.").alignment(Alignment::Center).block(Block::bordered().title("SSHDeck")); f.render_widget(p, area); return; } match app.view { crate::app::View::Dashboard=>views::dashboard::draw(f, app, area), crate::app::View::HostDetail=>views::host_detail::draw(f, app, area), crate::app::View::Files=>views::files::draw(f, app, area), crate::app::View::Tunnels=>views::tunnels::draw(f, app, area), crate::app::View::CommandRunner=>views::command_runner::draw(f, app, area), crate::app::View::Logs=>views::logs::draw(f, app, area), crate::app::View::Settings=>views::settings::draw(f, app, area), crate::app::View::Help=>views::help::draw(f, app, area) } if app.mode==Mode::Palette { modal::command_palette(f, app, area); } if app.mode==Mode::Search { modal::search(f, app, area); } if app.mode==Mode::Command { modal::command_mode(f, app, area); } if let Some(t)=&app.toast { toast::draw(f, app, t, area); } }
